# Secrets set on each Fly app at deploy time (T-09.03, SPEC 5 rule 10 and 11). NO VALUES here: a template names GitHub *environment* secrets (environment "staging")
# as ${NAME}. scripts/deploy/set-secrets.sh expands the template and runs `fly secrets set --stage` (applied by the deploy that follows). Values are masked and never echoed.
#
# app         fly_secret_name                         required|optional   template (the rest of the line)
# optional: skipped when a referenced GitHub secret is unset (the feature degrades visibly, P8); required: the deploy of that app fails, naming the missing GitHub secret.
#
# The five databases live on one PostgreSQL app (docs/operations/AUTH.md section 2). A password must not contain ; or " (generate it with openssl rand -base64 33).
postgres      POSTGRES_PASSWORD                       required  ${POSTGRES_PASSWORD}

authservice   ConnectionStrings__DefaultConnection    required  Host=gabinety-postgres-staging.internal;Port=5432;Database=authdb;Username=postgres;Password=${POSTGRES_PASSWORD}
authservice   Jwt__PrivateKeyPem                      required  ${AUTH_JWT_PRIVATE_KEY_PEM}
authservice   OAuth__GitHub__ClientId                 optional  ${AUTH_GITHUB_CLIENT_ID}
authservice   OAuth__GitHub__ClientSecret             optional  ${AUTH_GITHUB_CLIENT_SECRET}

# Internal keys (ADR-0007, F-03 / T-10.10): ONE KEY PER CALLER AND CALLEE PAIR, never shared. The callee holds the key of each caller as Internal__Callers__<Caller> and
# records the caller in the request; the caller holds the key it sends as Internal__Keys__<Callee> (CONTRACTS 10.3, SPEC 5.1). GitHub secret INTERNAL_KEY_<CALLER>_TO_<CALLEE>.
# Outside the fake profile a service refuses to start when a key is shorter than 43 characters (openssl rand -base64 33), is not base64url/hex, or two keys are equal.
# Internal__Key (one callee key) is NOT mapped any more: it exists only for the fake profile and tests. Assistant holds no Directory key (its taxonomy read is public).
# INTERNAL_KEY_OWNER_<CALLEE> (optional) is the owner's own key for the RUNBOOK 8 erasure hooks; unset means the hooks cannot be called until the owner stages one by hand.
directory     ConnectionStrings__directorydb          required  Host=gabinety-postgres-staging.internal;Port=5432;Database=directorydb;Username=postgres;Password=${POSTGRES_PASSWORD}
directory     Internal__Callers__Booking              required  ${INTERNAL_KEY_BOOKING_TO_DIRECTORY}
directory     Internal__Callers__Reputation           required  ${INTERNAL_KEY_REPUTATION_TO_DIRECTORY}
directory     Internal__Callers__Owner                optional  ${INTERNAL_KEY_OWNER_DIRECTORY}
directory     Internal__Keys__Booking                 required  ${INTERNAL_KEY_DIRECTORY_TO_BOOKING}

booking       ConnectionStrings__bookingdb            required  Host=gabinety-postgres-staging.internal;Port=5432;Database=bookingdb;Username=postgres;Password=${POSTGRES_PASSWORD}
booking       Internal__Callers__Reputation           required  ${INTERNAL_KEY_REPUTATION_TO_BOOKING}
booking       Internal__Callers__Directory            required  ${INTERNAL_KEY_DIRECTORY_TO_BOOKING}
booking       Internal__Callers__Owner                optional  ${INTERNAL_KEY_OWNER_BOOKING}
booking       Internal__Keys__Directory               required  ${INTERNAL_KEY_BOOKING_TO_DIRECTORY}
# E-mail (T-09.06, docs/operations/EMAIL.md): all optional. Notifications__Provider is Smtp ONLY when the host and the sender are both present (@if gate, see set-secrets.sh);
# otherwise it is not set and the code default Log applies, and Booking says so (startup warning, /health/details email: Degraded): it never claims delivery for a log line.
# The non-secret values are GitHub *secrets* too: this script reads the secrets context only, and a secret costs nothing. User and password: both or neither.
booking       Notifications__Provider                 optional  @if(NOTIFICATIONS_SMTP_HOST,NOTIFICATIONS_SMTP_FROM)Smtp
booking       Notifications__Smtp__Host               optional  ${NOTIFICATIONS_SMTP_HOST}
booking       Notifications__Smtp__FromAddress        optional  ${NOTIFICATIONS_SMTP_FROM}
booking       Notifications__Smtp__Port               optional  ${NOTIFICATIONS_SMTP_PORT}
booking       Notifications__Smtp__TlsMode            optional  ${NOTIFICATIONS_SMTP_TLS_MODE}
booking       Notifications__Smtp__User               optional  ${NOTIFICATIONS_SMTP_USER}
booking       Notifications__Smtp__Password           optional  ${NOTIFICATIONS_SMTP_PASSWORD}
# Payments (T-09.05, ADR proposal 0011): Stripe. Both required: the Booking host refuses to start with Payments__Provider=Stripe and either missing, so a deploy without them
# fails here, naming the GitHub secret (the Booking deploy gate of security review F-01 / PR 117 passes only when both exist). Values: docs/operations/PAYMENTS-GO-LIVE.md.
booking       Payments__Stripe__SecretKey             required  ${PAYMENTS_STRIPE_SECRET_KEY}
booking       Payments__Stripe__WebhookSecret         required  ${PAYMENTS_STRIPE_WEBHOOK_SECRET}

reputation    ConnectionStrings__reputationdb         required  Host=gabinety-postgres-staging.internal;Port=5432;Database=reputationdb;Username=postgres;Password=${POSTGRES_PASSWORD}
reputation    Internal__Callers__Owner                optional  ${INTERNAL_KEY_OWNER_REPUTATION}
reputation    Internal__Keys__Directory               required  ${INTERNAL_KEY_REPUTATION_TO_DIRECTORY}
reputation    Internal__Keys__Booking                 required  ${INTERNAL_KEY_REPUTATION_TO_BOOKING}
reputation    Internal__Keys__Assistant               required  ${INTERNAL_KEY_REPUTATION_TO_ASSISTANT}

assistant     ConnectionStrings__assistantdb          required  Host=gabinety-postgres-staging.internal;Port=5432;Database=assistantdb;Username=postgres;Password=${POSTGRES_PASSWORD}
assistant     Internal__Callers__Reputation           required  ${INTERNAL_KEY_REPUTATION_TO_ASSISTANT}
assistant     Internal__Callers__Owner                optional  ${INTERNAL_KEY_OWNER_ASSISTANT}
# The language model (T-09.07, COPILOT-SDK 6). Nothing here = the Assistant answers its documented "unavailable" state and the web shows the plain form (P8).
# Bring your own key: one custom model, Llm__CustomModels__0__*. Gated: set LLM_CUSTOM_ENDPOINT and LLM_CUSTOM_MODEL together or none of the group is staged (a half entry stops the host: LlmOptionsValidator).
# LLM_CUSTOM_PROVIDER_TYPE (anthropic | openai | azure, default openai), LLM_CUSTOM_WIRE_API (default chat-completions) and LLM_CUSTOM_API_KEY are optional extras of the group.
# NOTE: the Copilot runtime must be signed in for ANY model to run (CopilotLlmGateway.StartAsync): provide COPILOT_GITHUB_TOKEN as well (A-04: only after the owner records the terms decision).
assistant     Llm__CustomModels__0__Id                optional  @if(LLM_CUSTOM_ENDPOINT,LLM_CUSTOM_MODEL)${LLM_CUSTOM_MODEL}
assistant     Llm__CustomModels__0__Model             optional  @if(LLM_CUSTOM_ENDPOINT,LLM_CUSTOM_MODEL)${LLM_CUSTOM_MODEL}
assistant     Llm__CustomModels__0__BaseUrl           optional  @if(LLM_CUSTOM_ENDPOINT,LLM_CUSTOM_MODEL)${LLM_CUSTOM_ENDPOINT}
assistant     Llm__CustomModels__0__ProviderType      optional  @if(LLM_CUSTOM_ENDPOINT,LLM_CUSTOM_MODEL)${LLM_CUSTOM_PROVIDER_TYPE}
assistant     Llm__CustomModels__0__WireApi           optional  @if(LLM_CUSTOM_ENDPOINT,LLM_CUSTOM_MODEL)${LLM_CUSTOM_WIRE_API}
assistant     Llm__CustomModels__0__ApiKey            optional  @if(LLM_CUSTOM_ENDPOINT,LLM_CUSTOM_MODEL)${LLM_CUSTOM_API_KEY}
assistant     Copilot__GitHubToken                    optional  ${COPILOT_GITHUB_TOKEN}

# RateLimit__TrustedProxyKey (T-10.03, #110): the SAME value on web and the four backends. Web sends it as X-Edge-Key with the visitor's address; a service trusts that address only with the matching key.
# It is not an internal key and opens no route (the edge guard refuses /internal/* to a request that carries it). Optional: absent, the limiter falls back to one bucket per peer address (degrades, P8).
# Outside the fake profile it must be 43+ characters and different from every internal key (startup check, Gabinety.ServiceDefaults.Edge).
# web-blazor (the web host, deploy/estate.conf): its one secret; it holds no internal key and no session-signing secret (the Data Protection keys are on its volume).
web-blazor    RateLimit__TrustedProxyKey              optional  ${RATE_LIMIT_TRUSTED_PROXY_KEY}
directory     RateLimit__TrustedProxyKey              optional  ${RATE_LIMIT_TRUSTED_PROXY_KEY}
booking       RateLimit__TrustedProxyKey              optional  ${RATE_LIMIT_TRUSTED_PROXY_KEY}
reputation    RateLimit__TrustedProxyKey              optional  ${RATE_LIMIT_TRUSTED_PROXY_KEY}
assistant     RateLimit__TrustedProxyKey              optional  ${RATE_LIMIT_TRUSTED_PROXY_KEY}

# web-blazor holds no secret of its own besides that one (the session cookie is sealed with the Data Protection keys on its volume; the user's tokens never reach the browser).
